diff --git a/sistema/sistema.cpp b/sistema/sistema.cpp
index 761f866..bc15e28 100644
--- a/sistema/sistema.cpp
+++ b/sistema/sistema.cpp
@@ -1993,6 +1993,89 @@ extern "C" void c_cedebug(natl id, const char *buf, natq quanti)
 //   ESAME 2024-01-10 )

 // ( SOLUZIONE 2024-01-10
+
+/// Driver delle periferiche CE
+extern "C" void c_driver_ce(natl id)
+{
+	des_ce *ce = &array_ce[id];
+	
+	if (!ce->enabled)
+		return;
+	
+	natb byte = inputb(ce->iRBR);
+	*(ce->buf++) = byte;
+	ce->quanti--;
+	sem_signal(ce->sync);
+	
+	if (!ce->quanti) {
+		ce->enabled = false;
+		outputb(0, ce->iCTL);
+	}
+}
+
+/// Parte C++ della primitiva ceread_n_to()
+extern "C" bool c_ceread_n_to(natl id, char *buf, natl& quanti, natl to)
+{
+	if (id >= next_ce) {
+		flog(LOG_WARN, "ce non riconosciuto: %d", id);
+		c_abort_p();
+		return false;
+	}
+	
+	if (!to) {
+		flog(LOG_WARN, "timeout non valido");
+		c_abort_p();
+		return false;
+	}
+	
+	if (!buf) {
+		flog(LOG_WARN, "buffer non valido");
+		c_abort_p();
+		return false;
+	}
+	
+	if (!c_access((vaddr)&quanti, sizeof(natl), true)) {
+		flog(LOG_WARN, "quanti non accessibile");
+		c_abort_p();
+		return false;
+	}
+	
+	natl n = quanti;
+	
+	if (!c_access((vaddr)buf, n, true)) {
+		flog(LOG_WARN, "buffer non accessibile");
+		c_abort_p();
+		return false;
+	}
+	
+	des_ce *ce = &array_ce[id];
+	
+	if (!sem_wait_to(ce->mutex, to)) {
+		return false;
+	}
+	
+	ce->buf = buf;
+	ce->quanti = n;
+	ce->enabled = true;
+	outputb(1, ce->iCTL);
+	
+	bool result = true;
+	for (natl i = 0; i < n; i++) {
+		if (!sem_wait_to(ce->sync, to)) {
+			result = false;
+			break;
+		}
+	}
+	
+	if (!result) {
+		ce->enabled = false;
+		outputb(0, ce->iCTL);
+		quanti = n - ce->quanti;
+	}
+	
+	sem_signal(ce->mutex);
+	return result;
+}
 //   SOLUZIONE 2024-01-10 )

