diff --git a/sistema/sistema.s b/sistema/sistema.s
index 84b43db..02aa8ce 100644
--- a/sistema/sistema.s
+++ b/sistema/sistema.s
@@ -245,6 +245,8 @@ init_idt:
 	carica_gate	TIPO_CEDEBUG	a_cedebug	LIV_UTENTE
 //   ESAME 2024-01-10 )
 // ( SOLUZIONE 2024-01-10
+
+	carica_gate	TIPO_CEREADTO	a_ceread_n_to	LIV_UTENTE
 //   SOLUZIONE 2024-01-10 )

 	// primitive per il livello I/O (tipi 0x3-)
@@ -446,6 +448,19 @@ a_sem_wait_to:
 //   ESAME 2024-01-10 )

 // ( SOLUZIONE 2024-01-10
+
+	.extern c_ceread_n_to
+/// Parte Assembler della primitiva ceread_n_to()
+a_ceread_n_to:
+	.cfi_startproc
+	.cfi_def_cfa_offset 40
+	.cfi_offset rip, -40
+	.cfi_offset rsp, -16
+	call salva_stato
+	call c_ceread_n_to
+	call carica_stato
+	iretq
+	.cfi_endproc
 //   SOLUZIONE 2024-01-10 )

